# Install and load required visualization packages if you haven't already
# install.packages(c("ggplot2", "cluster"))
library(ggplot2)
library(cluster)

# 1. Load the morphological metrics generated by the U-Net
data <- read.csv(file.choose())

# 2. Isolate and scale the numerical features
# This ensures large volume numbers don't overpower the hypertrophy index in the math
features <- data[, c("myocardium_volume_px", "lv_cavity_volume_px", "hypertrophy_index")]
features_scaled <- scale(features)

# 3. Principal Component Analysis (PCA)
# Reduces the 3 dimensions into 2 primary axes of morphological variance
pca_result <- prcomp(features_scaled)
pca_data <- as.data.frame(pca_result$x)
pca_data$patient_id <- data$patient_id

# 4. K-Means Clustering
# We group the patients into 3 phenotypes (e.g., Normal, Mild Hypertrophy, Severe HCM)
set.seed(42)
kmeans_result <- kmeans(features_scaled, centers = 3, nstart = 25)
pca_data$phenogroup <- as.factor(kmeans_result$cluster)

# Append the cluster assignments back to the original clinical data
data$phenogroup <- pca_data$phenogroup
write.csv(data, "hcm_phenogroups_final.csv", row.names = FALSE)

# 5. Visualize the Phenogroups
ggplot(pca_data, aes(x = PC1, y = PC2, color = phenogroup)) +
  geom_point(size = 4, alpha = 0.8) +
  stat_ellipse(level = 0.95, linetype = 2) + # Adds a 95% confidence boundary around clusters
  theme_minimal(base_size = 14) +
  labs(
    title = "HCM Morphological Taxonomy",
    subtitle = "PCA of U-Net Derived Cardiac Metrics (Volume & Hypertrophy)",
    x = paste0("Principal Component 1 (", round(summary(pca_result)$importance[2,1] * 100, 1), "% Variance)"),
    y = paste0("Principal Component 2 (", round(summary(pca_result)$importance[2,2] * 100, 1), "% Variance)"),
    color = "Phenogroup"
  ) +
  scale_color_manual(values = c("#00b4d8", "#ffb703", "#e63946"))

